import React from 'react';
import Flashcard from './Flashcard';
import { flashcards } from '../data/flashcards';


const FlashcardList: React.FC = () => {
    const [current, setCurrent] = React.useState(0);
    const total = flashcards.length;

    const goPrev = () => setCurrent((prev) => (prev > 0 ? prev - 1 : prev));
    const goNext = () => setCurrent((prev) => (prev < total - 1 ? prev + 1 : prev));

    return (
        <div style={{textAlign: 'center'}}>
            <h2>Click the card to flip!</h2>
            <div className="flashcard-list" style={{justifyContent: 'center'}}>
                <Flashcard question={flashcards[current].question} answer={flashcards[current].answer} />
            </div>
            <div style={{marginTop: 20}}>
                <button onClick={goPrev} disabled={current === 0} style={{marginRight: 10}}>Previous</button>
                <span>{current + 1} / {total}</span>
                <button onClick={goNext} disabled={current === total - 1} style={{marginLeft: 10}}>Next</button>
            </div>
        </div>
    );
};

export default FlashcardList;